44	export async function getRipgrepPath(): Promise<string | null> {
45	  const platform = os.platform();
46	  const arch = os.arch();
47	
48	  // Map to the correct bundled binary
49	  const binName = `rg-${platform}-${arch}${platform === 'win32' ? '.exe' : ''}`;
50	
51	  const candidatePaths = [
52	    // 1. SEA runtime layout: everything is flattened into the root dir
53	    path.resolve(__dirname, 'vendor/ripgrep', binName),
54	    // 2. Dev/Dist layout: packages/core/dist/tools/ripGrep.js -> packages/core/vendor/ripgrep
55	    path.resolve(__dirname, '../../vendor/ripgrep', binName),
56	  ];
57	
58	  for (const candidate of candidatePaths) {
59	    if (await fileExists(candidate)) {
60	      return candidate;
61	    }
62	  }
63	
64	  return null;
65	}
