14	/**
15	 * Determines if a command is strictly approved for execution on macOS.
16	 * A command is approved if it's composed entirely of tools explicitly listed in `approvedTools`
17	 * OR if it's composed of known safe, read-only POSIX commands.
18	 *
19	 * @param command - The full command string to execute.
20	 * @param args - The arguments for the command.
21	 * @param approvedTools - A list of explicitly approved tool names (e.g., ['npm', 'git']).
22	 * @returns true if the command is strictly approved, false otherwise.
23	 */
24	export async function isStrictlyApproved(
25	  command: string,
26	  args: string[],
27	  approvedTools?: string[],
28	): Promise<boolean> {
29	  const tools = approvedTools ?? [];
30	
31	  await initializeShellParsers();
32	
33	  const fullCmd = [command, ...args].join(' ');
34	  const stripped = stripShellWrapper(fullCmd);
35	
36	  const pipelineCommands = splitCommands(stripped);
37	
38	  // Fallback for simple commands or parsing failures
39	  if (pipelineCommands.length === 0) {
40	    // For simple commands, we check the root command.
41	    // If it's explicitly approved OR it's a known safe POSIX command, we allow it.
42	    return tools.includes(command) || isKnownSafeCommand([command, ...args]);
43	  }
44	
45	  // Check every segment of the pipeline
46	  return pipelineCommands.every((cmdString) => {
47	    const trimmed = cmdString.trim();
48	    if (!trimmed) return true;
49	
50	    const parsedArgs = shellParse(trimmed).map(extractStringFromParseEntry);
51	    if (parsedArgs.length === 0) return true;
52	
53	    const root = parsedArgs[0];
54	    // The segment is approved if the root tool is in the allowlist OR if the whole segment is safe.
55	    return tools.includes(root) || isKnownSafeCommand(parsedArgs);
56	  });
57	}
