119	/**
120	 * Core validation logic that checks a single command and its arguments
121	 * against an allowlist of known safe operations. It performs deep validation
122	 * for specific tools like `base64`, `find`, `rg`, `git`, and `sed` to ensure
123	 * unsafe flags (like `--output`, `-exec`, or mutating options) are not used.
124	 *
125	 * @param args - The command and its arguments.
126	 * @returns true if the command is strictly read-only and safe.
127	 */
128	function isSafeToCallWithExec(args: string[]): boolean {
129	  if (!args || args.length === 0) return false;
130	  const cmd = args[0];
131	
132	  const safeCommands = new Set([
133	    '__read',
134	    '__write',
135	    'cat',
136	    'cd',
137	    'cut',
138	    'echo',
139	    'expr',
140	    'false',
141	    'grep',
142	    'head',
143	    'id',
144	    'ls',
145	    'nl',
146	    'paste',
147	    'pwd',
148	    'rev',
149	    'seq',
150	    'stat',
151	    'tail',
152	    'tr',
153	    'true',
154	    'uname',
155	    'uniq',
156	    'wc',
157	    'which',
158	    'whoami',
159	    'numfmt',
160	    'tac',
161	  ]);
162	
163	  if (safeCommands.has(cmd)) {
164	    return true;
165	  }
166	
167	  if (cmd === 'base64') {
168	    const unsafeOptions = new Set(['-o', '--output']);
169	    return !args
170	      .slice(1)
171	      .some(
172	        (arg) =>
173	          unsafeOptions.has(arg) ||
174	          arg.startsWith('--output=') ||
175	          (arg.startsWith('-o') && arg !== '-o'),
176	      );
177	  }
178	
179	  if (cmd === 'find') {
180	    const unsafeOptions = new Set([
181	      '-exec',
182	      '-execdir',
183	      '-ok',
184	      '-okdir',
185	      '-delete',
186	      '-fls',
187	      '-fprint',
188	      '-fprint0',
189	      '-fprintf',
190	    ]);
191	    return !args.some((arg) => unsafeOptions.has(arg));
192	  }
193	
194	  if (cmd === 'rg') {
195	    const unsafeWithArgs = new Set(['--pre', '--hostname-bin']);
196	    const unsafeWithoutArgs = new Set(['--search-zip', '-z']);
197	
198	    return !args.some((arg) => {
199	      if (unsafeWithoutArgs.has(arg)) return true;
200	      for (const opt of unsafeWithArgs) {
201	        if (arg === opt || arg.startsWith(opt + '=')) return true;
202	      }
203	      return false;
204	    });
205	  }
206	
207	  if (cmd === 'git') {
208	    if (gitHasConfigOverrideGlobalOption(args)) {
